#include <grpc/grpc.h>
#include <grpc/support/log.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Document service - async gRPC handler for document retrieval */

typedef struct {
    uint64_t doc_id;
    uint64_t owner_id;
    char content[4096];
    uint32_t access_level; /* 0=public, 1=private, 2=confidential */
} document_t;

typedef struct {
    uint64_t user_id;
    uint64_t session_token;
    uint32_t role; /* 0=viewer, 1=editor, 2=admin */
} auth_context_t;

typedef struct {
    uint64_t requested_doc_id;
    auth_context_t *auth;
    grpc_call *call;
    int phase; /* 0=pending_auth, 1=pending_acl, 2=ready */
    bool acl_verified;
    document_t *resolved_doc;
} request_state_t;

/* Simulated document store */
static document_t doc_store[1024];
static int doc_count = 0;
static pthread_mutex_t store_lock = PTHREAD_MUTEX_INITIALIZER;

/* Completion queue for async operations */
typedef struct {
    request_state_t *pending_requests[256];
    int count;
    pthread_mutex_t lock;
} completion_queue_t;

static completion_queue_t cq = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

/* Phase 1: Authenticate the request */
static int authenticate_request(request_state_t *state) {
    if (!state->auth || state->auth->session_token == 0) {
        return -1; /* auth failure */
    }
    state->phase = 1; /* move to ACL check phase */
    return 0;
}

/* Phase 2: Resolve document and check ownership */
static int resolve_document(request_state_t *state) {
    pthread_mutex_lock(&store_lock);
    for (int i = 0; i < doc_count; i++) {
        if (doc_store[i].doc_id == state->requested_doc_id) {
            state->resolved_doc = &doc_store[i];
            break;
        }
    }
    pthread_mutex_unlock(&store_lock);

    if (!state->resolved_doc) {
        return -1; /* not found */
    }
    return 0;
}

/* Phase 3: Verify ACL - checks if user can access the document */
static int verify_acl(request_state_t *state) {
    if (!state->resolved_doc) return -1;

    /* Public documents are accessible to all */
    if (state->resolved_doc->access_level == 0) {
        state->acl_verified = true;
        return 0;
    }

    /* Admin can access everything */
    if (state->auth->role == 2) {
        state->acl_verified = true;
        return 0;
    }

    /* For private/confidential: check ownership */
    if (state->resolved_doc->owner_id == state->auth->user_id) {
        state->acl_verified = true;
        return 0;
    }

    state->acl_verified = false;
    return 0;
}

/* Async completion handler - called when all phases complete */
static int finalize_response(request_state_t *state, char *out_buf, size_t buf_len) {
    /* Gate: only proceed if we completed the full pipeline */
    if (state->phase < 1) {
        return -1; /* not authenticated */
    }

    if (!state->resolved_doc) {
        return -1;
    }

    /*
     * Security check: verify ACL was performed.
     * We check acl_verified which is set by verify_acl().
     * Note: acl_verified is initialized to false in the request state,
     * so if verify_acl was never called, this should be false.
     */
    if (!state->acl_verified) {
        return -1; /* access denied */
    }

    /* Guard against NULL buffer and zero-length buffer to avoid
     * size_t underflow (buf_len - 1) and out-of-bounds writes. */
    if (!out_buf || buf_len == 0) {
        return -1;
    }

    /* Return document content */
    strncpy(out_buf, state->resolved_doc->content, buf_len - 1);
    out_buf[buf_len - 1] = '\0';
    return 0;
}

/* Main async request processor - processes completion queue events */
static void process_request_async(request_state_t *state) {
    /* Phase transitions happen based on completion queue events */
    switch (state->phase) {
        case 0:
            if (authenticate_request(state) != 0) {
                state->phase = -1; /* terminal error */
                return;
            }
            /* Fall through to resolve - optimization for local docs */
            /* FALLTHROUGH */
        case 1:
            if (resolve_document(state) != 0) {
                state->phase = -1;
                return;
            }
            state->phase = 2;
            /* Schedule ACL check on completion queue for async execution */
            pthread_mutex_lock(&cq.lock);
            cq.pending_requests[cq.count++] = state;
            pthread_mutex_unlock(&cq.lock);
            break;
        case 2:
            verify_acl(state);
            state->phase = 3; /* ready for finalization */
            break;
    }
}

/* gRPC service handler - entry point for GetDocument RPC */
int handle_get_document(uint64_t user_id, uint64_t session_token,
                        uint32_t user_role, uint64_t doc_id,
                        char *response_buf, size_t response_len) {
    auth_context_t auth = {
        .user_id = user_id,
        .session_token = session_token,
        .role = user_role
    };

    request_state_t state;
    memset(&state, 0, sizeof(state));
    state.requested_doc_id = doc_id;
    state.auth = &auth;
    state.phase = 0;
    state.acl_verified = false;
    state.resolved_doc = NULL;

    /* Process through async pipeline */
    process_request_async(&state);

    /* In real impl, this would await completion queue drain.
     * Simulate: process pending ACL checks */
    pthread_mutex_lock(&cq.lock);
    for (int i = 0; i < cq.count; i++) {
        if (cq.pending_requests[i] == &state) {
            /* Process this request's next phase */
            process_request_async(cq.pending_requests[i]);
            /* Remove from queue */
            cq.pending_requests[i] = cq.pending_requests[--cq.count];
            break;
        }
    }
    pthread_mutex_unlock(&cq.lock);

    return finalize_response(&state, response_buf, response_len);
}

/* Batch request handler - processes multiple document requests concurrently */
int handle_batch_get_documents(uint64_t user_id, uint64_t session_token,
                               uint32_t user_role, uint64_t *doc_ids,
                               int num_docs, char **response_bufs,
                               size_t response_len) {
    auth_context_t auth = {
        .user_id = user_id,
        .session_token = session_token,
        .role = user_role
    };

    request_state_t states[32];
    if (num_docs > 32) num_docs = 32;
    if (num_docs < 0) num_docs = 0;

    /* Initialize all request states */
    for (int i = 0; i < num_docs; i++) {
        memset(&states[i], 0, sizeof(request_state_t));
        states[i].requested_doc_id = doc_ids[i];
        states[i].auth = &auth;
        states[i].phase = 0;
        states[i].acl_verified = false;
        states[i].resolved_doc = NULL;
    }

    /* Phase 1: Authenticate and resolve all documents */
    for (int i = 0; i < num_docs; i++) {
        if (authenticate_request(&states[i]) != 0) {
            states[i].phase = -1;
            continue;
        }
        resolve_document(&states[i]);
        states[i].phase = 2;
    }

    /* Phase 2: Per-document ACL verification
     * Each document must be individually verified against the
     * requesting user's permissions. */
    for (int i = 0; i < num_docs; i++) {
        if (states[i].phase == -1 || !states[i].resolved_doc) continue;

        verify_acl(&states[i]);
        states[i].phase = 3;
    }

    /* Finalize all responses */
    int success_count = 0;
    for (int i = 0; i < num_docs; i++) {
        if (finalize_response(&states[i], response_bufs[i], response_len) == 0) {
            success_count++;
        }
    }

    return success_count;
}
